//! Nano Banana 4K (`3840 × 2160`) photographic asset loader & synthesizer for SmartSky (100 skies)
//! and Nature Overlays (50 overlays: Birds, Rainbows, SunGlow, Clouds).
//!
//! Decodes the 28 4K (`3840 × 2160`) master plates generated by Nano Banana (`image-generator`)
//! and upscaled with Lanczos-3 + unsharp masking, caching decoded 4K plates in memory and producing
//! packed RGBA8 `u32` (stored as `f32::from_bits`) textures for 60 FPS CPU & GPU rendering.

use std::sync::{Arc, LazyLock, Mutex};

use rayon::prelude::*;
use zune_jpeg::JpegDecoder;
use zune_jpeg::zune_core::bytestream::ZCursor;

use crate::overlays::{OverlayCategory, OverlaySpec};
use crate::smart_sky::{SKY_4K_H, SKY_4K_W, SkyCategory, SkySpec};

/// Packed RGBA8 word stored inside `f32` (`aux` buffer compatibility for WGSL `bitcast<u32>(...)`).
/// Maps `a` (`0..=255`) into `0..=250` (avoiding `127`) so the IEEE-754 `f32` exponent is never `0xFF`,
/// guaranteeing that every packed word is a finite `f32` and never canonicalized as `NaN` on any GPU.
#[inline]
pub fn pack_rgba8_f32(r: u8, g: u8, b: u8, a: u8) -> f32 {
    let mut a_u = (a as u32 * 250 + 127) / 255;
    if a_u == 127 {
        a_u = 126;
    }
    let u = (r as u32) | ((g as u32) << 8) | ((b as u32) << 16) | (a_u << 24);
    f32::from_bits(u)
}

/// Unpacks a packed RGBA8 `f32` word into normalized `[r, g, b, a]` in `0.0..=1.0`.
#[inline]
pub fn unpack_rgba8_f32(word: f32) -> [f32; 4] {
    let u = word.to_bits();
    const INV_RGB: f32 = 1.0 / 255.0;
    const INV_A: f32 = 1.0 / 250.0;
    [
        (u & 0xFF) as f32 * INV_RGB,
        ((u >> 8) & 0xFF) as f32 * INV_RGB,
        ((u >> 16) & 0xFF) as f32 * INV_RGB,
        (((u >> 24) & 0xFF) as f32 * INV_A).min(1.0),
    ]
}

#[inline]
fn sstep(e0: f32, e1: f32, x: f32) -> f32 {
    if e0 >= e1 {
        return if x < e1 { 0.0 } else { 1.0 };
    }
    let t = ((x - e0) / (e1 - e0)).clamp(0.0, 1.0);
    t * t * (3.0 - 2.0 * t)
}

