/// Decoded 4K RGB8 master plate (`width × height × 3` bytes).
pub struct DecodedMaster {
    pub width: usize,
    pub height: usize,
    pub rgb: Vec<u8>,
    /// Mean zenith RGB (`0..1`) and mean horizon RGB (`0..1`) of this master plate for color transfer.
    pub mean_zenith: [f32; 3],
    pub mean_horizon: [f32; 3],
}

impl DecodedMaster {
    #[inline]
    pub fn sample_bilinear_srgb(&self, u: f32, v: f32) -> [f32; 3] {
        let fw = self.width as f32;
        let fh = self.height as f32;
        let fx = (u.clamp(0.0, 1.0) * (fw - 1.0)).clamp(0.0, (fw - 1.0001).max(0.0));
        let fy = (v.clamp(0.0, 1.0) * (fh - 1.0)).clamp(0.0, (fh - 1.0001).max(0.0));
        let x0 = fx as usize;
        let y0 = fy as usize;
        let x1 = (x0 + 1).min(self.width.saturating_sub(1));
        let y1 = (y0 + 1).min(self.height.saturating_sub(1));
        let tx = fx - x0 as f32;
        let ty = fy - y0 as f32;
        let i00 = (y0 * self.width + x0) * 3;
        let i10 = (y0 * self.width + x1) * 3;
        let i01 = (y1 * self.width + x0) * 3;
        let i11 = (y1 * self.width + x1) * 3;
        const INV: f32 = 1.0 / 255.0;
        let mut out = [0.0f32; 3];
        for c in 0..3 {
            let top = self.rgb[i00 + c] as f32 * (1.0 - tx) + self.rgb[i10 + c] as f32 * tx;
            let bot = self.rgb[i01 + c] as f32 * (1.0 - tx) + self.rgb[i11 + c] as f32 * tx;
            out[c] = (top * (1.0 - ty) + bot * ty) * INV;
        }
        out
    }
}

static MASTER_CACHE: LazyLock<Mutex<Vec<(MasterId, Arc<DecodedMaster>)>>> =
    LazyLock::new(|| Mutex::new(Vec::new()));

/// Decodes and caches a 4K (`3840 × 2160`) Nano Banana master plate.
pub fn get_master(id: MasterId) -> Arc<DecodedMaster> {
    if let Ok(guard) = MASTER_CACHE.lock()
        && let Some((_, m)) = guard.iter().find(|(k, _)| *k == id)
    {
        return m.clone();
    }
    let decoded = Arc::new(decode_master(id));
    if let Ok(mut guard) = MASTER_CACHE.lock() {
        if guard.len() >= 32 {
            guard.remove(0);
        }
        guard.push((id, decoded.clone()));
    }
    decoded
}

fn decode_master(id: MasterId) -> DecodedMaster {
    let bytes = id.jpeg_bytes();
    let cursor = ZCursor::new(bytes);
    let mut decoder = JpegDecoder::new(cursor);
    let rgb = decoder.decode().unwrap_or_default();
    let (width, height) = decoder.dimensions().unwrap_or((SKY_4K_W, SKY_4K_H));
    if width == 0 || height == 0 || rgb.len() < width * height * 3 {
        return DecodedMaster {
            width: 1,
            height: 1,
            rgb: vec![128, 128, 128],
            mean_zenith: [0.5, 0.5, 0.5],
            mean_horizon: [0.5, 0.5, 0.5],
        };
    }

    // Compute mean zenith (top 20%) and mean horizon (bottom 20%) colors for gentle per-preset color grading
    let mut zen_sum = [0.0f64; 3];
    let mut zen_n = 0usize;
    let mut hor_sum = [0.0f64; 3];
    let mut hor_n = 0usize;
    let step_x = (width / 32).max(1);
    let step_y = (height / 24).max(1);
    for y in (0..height / 4).step_by(step_y) {
        for x in (0..width).step_by(step_x) {
            let i = (y * width + x) * 3;
            zen_sum[0] += rgb[i] as f64 / 255.0;
            zen_sum[1] += rgb[i + 1] as f64 / 255.0;
            zen_sum[2] += rgb[i + 2] as f64 / 255.0;
            zen_n += 1;
        }
    }
    for y in ((height * 3) / 4..height).step_by(step_y) {
        for x in (0..width).step_by(step_x) {
            let i = (y * width + x) * 3;
            hor_sum[0] += rgb[i] as f64 / 255.0;
            hor_sum[1] += rgb[i + 1] as f64 / 255.0;
            hor_sum[2] += rgb[i + 2] as f64 / 255.0;
            hor_n += 1;
        }
    }
    let zn = zen_n.max(1) as f64;
    let hn = hor_n.max(1) as f64;
    DecodedMaster {
        width,
        height,
        rgb,
        mean_zenith: [
            (zen_sum[0] / zn) as f32,
            (zen_sum[1] / zn) as f32,
            (zen_sum[2] / zn) as f32,
        ],
        mean_horizon: [
            (hor_sum[0] / hn) as f32,
            (hor_sum[1] / hn) as f32,
            (hor_sum[2] / hn) as f32,
        ],
    }
}

/// Builds a packed RGBA8 buffer (`out_w × out_h` `f32` words) for SmartSky preset `spec` (`1..=100`)
/// from the 4K Nano Banana sky master plates.
pub fn build_sky_packed_map(spec: &SkySpec, out_w: usize, out_h: usize, defocus: f32) -> Vec<f32> {
    let sub = match spec.category {
        SkyCategory::Clear => (spec.index - 1) as usize,
        SkyCategory::Clouds => (spec.index - 3) as usize,
        SkyCategory::Overcast => (spec.index - 33) as usize,
        SkyCategory::Rainbow => (spec.index - 53) as usize,
        SkyCategory::Night => (spec.index - 63) as usize,
        SkyCategory::Psychedelic => (spec.index - 71) as usize,
        SkyCategory::Sunset => (spec.index - 81) as usize,
    };

    let master_id = match spec.category {
        SkyCategory::Clear => MasterId::SkyClear01,
        SkyCategory::Clouds => match sub % 3 {
            0 => MasterId::SkyClouds01,
            1 => MasterId::SkyClouds02,
            _ => MasterId::SkyClouds03,
        },
        SkyCategory::Overcast => match sub % 2 {
            0 => MasterId::SkyOvercast01,
            _ => MasterId::SkyOvercast02,
        },
        SkyCategory::Rainbow => match sub % 2 {
            0 => MasterId::SkyRainbow01,
            _ => MasterId::SkyRainbow02,
        },
        SkyCategory::Night => match sub % 2 {
            0 => MasterId::SkyNight01,
            _ => MasterId::SkyNight02,
        },
        SkyCategory::Psychedelic => match sub % 2 {
            0 => MasterId::SkyPsych01,
            _ => MasterId::SkyPsych02,
        },
        SkyCategory::Sunset => match sub % 4 {
            0 => MasterId::SkySunset01,
            1 => MasterId::SkySunset02,
            2 => MasterId::SkySunset03,
            _ => MasterId::SkySunset04,
        },
    };

    let master = get_master(master_id);

    // Curated horizontal pan, zoom crop, and optional mirror so every preset in the category
    // has its own distinct cloud formation layout while staying 100% photographic 4K
    let variant_group = sub / match spec.category {
        SkyCategory::Clear => 1,
        SkyCategory::Clouds => 3,
        SkyCategory::Overcast => 2,
        SkyCategory::Rainbow => 2,
        SkyCategory::Night => 2,
        SkyCategory::Psychedelic => 2,
        SkyCategory::Sunset => 4,
    };
    let mirror_x = (variant_group % 2) == 1;
    let zoom = 1.0 - (variant_group % 4) as f32 * 0.045; // 1.0 .. 0.865
    let pan_x = match variant_group % 5 {
        0 => 0.5,
        1 => 0.32,
        2 => 0.68,
        3 => 0.22,
        _ => 0.78,
    };
    let pan_y = match variant_group % 3 {
        0 => 0.50,
        1 => 0.44,
        _ => 0.56,
    };

    let target_zen = spec.zenith_rgb.map(|c| c as f32 / 255.0);
    let target_hor = spec.horizon_rgb.map(|c| c as f32 / 255.0);
    let target_cld = spec.cloud_rgb.map(|c| c as f32 / 255.0);

    // Subtle color-grade ratio between the preset's curated palette and the master plate's average
    let zen_shift = [
        (target_zen[0] - master.mean_zenith[0]) * 0.48,
        (target_zen[1] - master.mean_zenith[1]) * 0.48,
        (target_zen[2] - master.mean_zenith[2]) * 0.48,
    ];
    let hor_shift = [
        (target_hor[0] - master.mean_horizon[0]) * 0.52,
        (target_hor[1] - master.mean_horizon[1]) * 0.52,
        (target_hor[2] - master.mean_horizon[2]) * 0.52,
    ];
    let grade_str = if variant_group == 0 { 0.18f32 } else { 0.58f32 };

    // First build RGB8 at `out_w × out_h` in parallel
    let mut rgba_words = vec![0.0f32; out_w * out_h];
    rgba_words
        .par_chunks_mut(out_w)
        .enumerate()
        .for_each(|(y, row)| {
            let v0 = (y as f32 + 0.5) / out_h as f32;
            let sv = ((v0 - 0.5) * zoom + pan_y * (1.0 - zoom) + 0.5 * zoom).clamp(0.0, 1.0);
            let t_v = v0.powf(0.85);
            let shift = [
                (zen_shift[0] * (1.0 - t_v) + hor_shift[0] * t_v) * grade_str,
                (zen_shift[1] * (1.0 - t_v) + hor_shift[1] * t_v) * grade_str,
                (zen_shift[2] * (1.0 - t_v) + hor_shift[2] * t_v) * grade_str,
            ];
            for (x, slot) in row.iter_mut().enumerate() {
                let mut u0 = (x as f32 + 0.5) / out_w as f32;
                if mirror_x {
                    u0 = 1.0 - u0;
                }
                let su = ((u0 - 0.5) * zoom + pan_x * (1.0 - zoom) + 0.5 * zoom).clamp(0.0, 1.0);
                let mut rgb = master.sample_bilinear_srgb(su, sv);
                let lum = 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2];
                let hl_w = sstep(0.55, 0.92, lum) * grade_str * 0.30;
                for c in 0..3 {
                    let graded = rgb[c] + shift[c] * (0.35 + 0.65 * (1.0 - (lum - 0.5).abs()));
                    rgb[c] = (graded * (1.0 - hl_w) + target_cld[c] * hl_w).clamp(0.0, 1.0);
                }
                let r8 = (rgb[0] * 255.0 + 0.5) as u8;
                let g8 = (rgb[1] * 255.0 + 0.5) as u8;
                let b8 = (rgb[2] * 255.0 + 0.5) as u8;
                *slot = pack_rgba8_f32(r8, g8, b8, 255);
            }
        });

    if defocus > 1.0 {
        let radius = ((defocus / 100.0) * (out_w as f32 * 0.012)).round() as usize;
        if radius > 0 {
            rgba_words = box_blur_packed_rgba8(&rgba_words, out_w, out_h, radius);
        }
    }

    rgba_words
}

/// Builds a packed RGBA8 buffer (`out_w × out_h` `f32` words) for the 50 Nano Banana 4K Nature Overlays
/// (`151..=200`: Birds, Rainbows, SunGlow, Clouds).
pub fn build_nature_overlay_packed_map(
    spec: &OverlaySpec,
    out_w: usize,
    out_h: usize,
    blur: f32,
) -> Vec<f32> {
    let sub_idx = match spec.category {
        OverlayCategory::Birds => (spec.index - 151) as usize,
        OverlayCategory::Rainbows => (spec.index - 161) as usize,
        OverlayCategory::SunGlow => (spec.index - 171) as usize,
        OverlayCategory::Clouds => (spec.index - 181) as usize,
        _ => 0,
    };

    let ca = spec.color_a.map(|c| c as f32 / 255.0);
    let cb = spec.color_b.map(|c| c as f32 / 255.0);

    let mut rgba_words = vec![pack_rgba8_f32(0, 0, 0, 0); out_w * out_h];

    match spec.category {
        OverlayCategory::Birds => {
            // Select the 4K Nano Banana bird master plate(s) and composition transform
            let (master_id, on_white_bg, mirror_x, zoom, off_x, off_y, tint_strength) = match sub_idx {
                0 => (MasterId::Birds01, true, false, 1.0f32, 0.0f32, -0.10f32, 0.0f32), // Bandada en V
                1 => (MasterId::Birds03, true, false, 1.05, 0.0, -0.06, 0.55),           // Gaviotas al Sol (golden rim)
                2 => (MasterId::Birds02, false, false, 1.15, 0.0, -0.05, 0.0),           // Palomas Nupciales (white doves on black!)
                3 => (MasterId::Birds01, true, true, 1.55, 0.05, -0.16, 0.15),           // Aves del Horizonte (distant smaller flock)
                4 => (MasterId::Birds03, true, false, 0.96, 0.0, -0.04, 0.0),            // Bandada Ascendente
                5 => (MasterId::Birds02, false, true, 1.30, -0.04, -0.10, 0.15),         // Dúo en Libertad
                6 => (MasterId::Birds01, true, true, 1.05, -0.03, -0.08, 0.65),          // Vuelo de Atardecer (warm sunset tint)
                7 => (MasterId::Birds03, true, true, 1.12, 0.02, -0.12, 0.10),           // Cielo de Golondrinas
                8 => (MasterId::Birds04, true, false, 1.10, 0.0, -0.08, 0.0),            // Águila en Cumbre (Majestic Golden Eagle!)
                _ => (MasterId::Birds03, true, false, 0.90, 0.0, -0.08, 0.10),           // Gran Migración
            };
            let master = get_master(master_id);
            let extra_master = if sub_idx == 9 {
                Some(get_master(MasterId::Birds01))
            } else {
                None
            };

            rgba_words
                .par_chunks_mut(out_w)
                .enumerate()
                .for_each(|(y, row)| {
                    let v0 = (y as f32 + 0.5) / out_h as f32;
                    let sv = (v0 - 0.5 + off_y) * zoom + 0.5;
                    for (x, slot) in row.iter_mut().enumerate() {
                        let mut u0 = (x as f32 + 0.5) / out_w as f32;
                        if mirror_x {
                            u0 = 1.0 - u0;
                        }
                        let su = (u0 - 0.5 + off_x) * zoom + 0.5;
                        let mut final_rgba = [0.0f32; 4];

                        if (0.0..=1.0).contains(&su) && (0.0..=1.0).contains(&sv) {
                            let raw = master.sample_bilinear_srgb(su, sv);
                            final_rgba = extract_bird_rgba(raw, on_white_bg, ca, cb, tint_strength);
                        }

                        // For "Gran Migración" (sub_idx == 9), layer the second 4K flock alongside the first
                        if let Some(m2) = &extra_master {
                            let su2 = (u0 - 0.5 - 0.12) * 1.25 + 0.5;
                            let sv2 = (v0 - 0.5 + 0.18) * 1.25 + 0.5;
                            if (0.0..=1.0).contains(&su2) && (0.0..=1.0).contains(&sv2) {
                                let raw2 = m2.sample_bilinear_srgb(su2, sv2);
                                let rgba2 = extract_bird_rgba(raw2, true, ca, cb, tint_strength);
                                if rgba2[3] > final_rgba[3] {
                                    final_rgba = rgba2;
                                }
                            }
                        }

                        if final_rgba[3] > 0.002 {
                            let r8 = (final_rgba[0].clamp(0.0, 1.0) * 255.0 + 0.5) as u8;
                            let g8 = (final_rgba[1].clamp(0.0, 1.0) * 255.0 + 0.5) as u8;
                            let b8 = (final_rgba[2].clamp(0.0, 1.0) * 255.0 + 0.5) as u8;
                            let a8 = (final_rgba[3].clamp(0.0, 1.0) * 255.0 + 0.5) as u8;
                            *slot = pack_rgba8_f32(r8, g8, b8, a8);
                        }
                    }
                });
        }
        OverlayCategory::Rainbows => {
            let master_id = match sub_idx {
                1 | 0 | 4 | 6 | 8 => MasterId::Rainbow01, // Primary + double rainbow
                _ => MasterId::Rainbow02,                 // Pastel wedding / misty rainbow
            };
            let master = get_master(master_id);
            let (mirror_x, zoom, off_x, off_y, sat_boost) = match sub_idx {
                0 => (false, 1.00f32, 0.00f32, 0.00f32, 1.05f32), // Arcoíris Real
                1 => (false, 0.94, 0.00, 0.02, 1.15),             // Arcoíris Doble
                2 => (false, 1.00, 0.00, 0.00, 0.92),             // Arcoíris Nupcial
                3 => (true, 0.96, 0.00, -0.02, 0.95),             // Arco en la Bruma
                4 => (false, 0.88, 0.00, 0.05, 1.08),             // Puente Celestial
                5 => (true, 1.00, 0.00, 0.00, 1.05),              // Arcoíris Hora Dorada
                6 => (false, 0.68, 0.22, 0.04, 1.10),             // Destello Tras Lluvia (Right branch)
                7 => (false, 0.68, -0.22, 0.04, 1.05),            // Brisa Irisada (Left branch)
                8 => (true, 0.95, 0.00, -0.03, 1.12),             // Arcoíris Alpino
                _ => (false, 0.58, 0.15, -0.08, 1.05),            // Fragmento Espectral
            };
            let warm_tint = if sub_idx == 5 { 0.22f32 } else { 0.0f32 };

            rgba_words
                .par_chunks_mut(out_w)
                .enumerate()
                .for_each(|(y, row)| {
                    let v0 = (y as f32 + 0.5) / out_h as f32;
                    let sv = (v0 - 0.5) * zoom + 0.5 + off_y;
                    let bot_fade = 1.0 - sstep(0.82, 0.99, v0);
                    for (x, slot) in row.iter_mut().enumerate() {
                        let mut u0 = (x as f32 + 0.5) / out_w as f32;
                        if mirror_x {
                            u0 = 1.0 - u0;
                        }
                        let su = (u0 - 0.5) * zoom + 0.5 + off_x;
                        if (0.0..=1.0).contains(&su) && (0.0..=1.0).contains(&sv) {
                            let mut rgb = master.sample_bilinear_srgb(su, sv);
                            let lum = 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2];
                            let mx = rgb[0].max(rgb[1]).max(rgb[2]);
                            if mx > 0.015 {
                                for c in 0..3 {
                                    rgb[c] = (lum + (rgb[c] - lum) * sat_boost).clamp(0.0, 1.0);
                                }
                                if warm_tint > 0.0 {
                                    rgb[0] = (rgb[0] * (1.0 + warm_tint)).clamp(0.0, 1.0);
                                    rgb[2] = (rgb[2] * (1.0 - warm_tint * 0.7)).clamp(0.0, 1.0);
                                }
                                let a = (sstep(0.015, 0.42, mx) * bot_fade).clamp(0.0, 1.0);
                                let r8 = (rgb[0] * bot_fade * 255.0 + 0.5) as u8;
                                let g8 = (rgb[1] * bot_fade * 255.0 + 0.5) as u8;
                                let b8 = (rgb[2] * bot_fade * 255.0 + 0.5) as u8;
                                let a8 = (a * 255.0 + 0.5) as u8;
                                *slot = pack_rgba8_f32(r8, g8, b8, a8);
                            }
                        }
                    }
                });
        }
        OverlayCategory::SunGlow => {
            let master_id = match sub_idx {
                1 | 3 | 6 | 8 => MasterId::Sunglow02, // Multi-blade diamond sunstar
                _ => MasterId::Sunglow01,             // Warm golden-hour solar disc + Mie corona
            };
            let master = get_master(master_id);
            // Position the sun center cleanly according to the preset variant
            let (target_x, target_y, zoom) = match sub_idx {
                0 => (0.50f32, 0.28f32, 0.95f32), // Sol Dorado Real
                1 => (0.28, 0.26, 1.00),          // Estrella Solar 8P (upper-left)
                2 => (0.50, 0.46, 0.90),          // Sol de Atardecer (lower horizon)
                3 => (0.72, 0.26, 1.00),          // Sol Matutino Puro (upper-right)
                4 => (0.50, 0.32, 0.78),          // Resplandor Épico (large cine flare)
                5 => (0.34, 0.28, 0.95),          // Sol entre Nubes
                6 => (0.50, 0.26, 0.92),          // Sol Diamante 14P
                7 => (0.68, 0.30, 0.92),          // Sol Californiano
                8 => (0.50, 0.18, 1.05),          // Sol Cenital
                _ => (0.50, 0.42, 0.88),          // Sol Crepuscular
            };

            rgba_words
                .par_chunks_mut(out_w)
                .enumerate()
                .for_each(|(y, row)| {
                    let v0 = (y as f32 + 0.5) / out_h as f32;
                    let sv = (v0 - target_y) * zoom + 0.5;
                    for (x, slot) in row.iter_mut().enumerate() {
                        let u0 = (x as f32 + 0.5) / out_w as f32;
                        let su = (u0 - target_x) * zoom + 0.5;
                        // Gentle radial edge vignette so shifted sun never shows a hard rectangle edge
                        let edge_d = ((su - 0.5).hypot(sv - 0.5) * 2.0).clamp(0.0, 1.5);
                        let edge_fade = 1.0 - sstep(0.78, 0.99, edge_d);
                        if edge_fade > 0.002 && (0.0..=1.0).contains(&su) && (0.0..=1.0).contains(&sv) {
                            let raw = master.sample_bilinear_srgb(su, sv);
                            let mx = raw[0].max(raw[1]).max(raw[2]);
                            if mx > 0.01 {
                                let core_w = sstep(0.65, 0.98, mx);
                                let mut rgb = [0.0f32; 3];
                                for c in 0..3 {
                                    let tinted = raw[c] * (0.55 + 0.55 * ca[c]) + mx * cb[c] * 0.18;
                                    rgb[c] = (tinted * (1.0 - core_w * 0.5) + raw[c] * (core_w * 0.5)) * edge_fade;
                                }
                                let a = (sstep(0.01, 0.55, mx) * edge_fade).clamp(0.0, 1.0);
                                let r8 = (rgb[0].clamp(0.0, 1.0) * 255.0 + 0.5) as u8;
                                let g8 = (rgb[1].clamp(0.0, 1.0) * 255.0 + 0.5) as u8;
                                let b8 = (rgb[2].clamp(0.0, 1.0) * 255.0 + 0.5) as u8;
                                let a8 = (a * 255.0 + 0.5) as u8;
                                *slot = pack_rgba8_f32(r8, g8, b8, a8);
                            }
                        }
                    }
                });
        }
        OverlayCategory::Clouds => {
            let master_id = match sub_idx {
                0 | 2 | 5 | 8 | 10 | 14 | 17 | 19 => MasterId::CloudsOvl01, // Sculpted white cumulus
                1 | 6 | 9 | 13 | 16 => MasterId::CloudsOvl02,               // Delicate cirrus wisps
                3 | 7 | 11 | 15 | 18 => MasterId::CloudsOvl03,              // Golden-hour sunset cumulus
                _ => MasterId::CloudsOvl04,                                 // Rolling valley fog & mist
            };
            let master = get_master(master_id);
            let mirror_x = (sub_idx % 2) == 1;
            let zoom = 0.88 + (sub_idx % 4) as f32 * 0.06;
            let off_x = match sub_idx % 5 {
                0 => 0.0,
                1 => -0.06,
                2 => 0.06,
                3 => -0.10,
                _ => 0.10,
            };
            let off_y = match sub_idx {
                4 | 12 => -0.14f32, // Shift lower mist bank
                _ => 0.06 - (sub_idx % 3) as f32 * 0.04,
            };

            rgba_words
                .par_chunks_mut(out_w)
                .enumerate()
                .for_each(|(y, row)| {
                    let v0 = (y as f32 + 0.5) / out_h as f32;
                    let sv = (v0 - 0.5 + off_y) * zoom + 0.5;
                    for (x, slot) in row.iter_mut().enumerate() {
                        let mut u0 = (x as f32 + 0.5) / out_w as f32;
                        if mirror_x {
                            u0 = 1.0 - u0;
                        }
                        let su = (u0 - 0.5 + off_x) * zoom + 0.5;
                        let edge_x = sstep(0.0, 0.06, su) * (1.0 - sstep(0.94, 1.0, su));
                        let edge_y = sstep(0.0, 0.06, sv) * (1.0 - sstep(0.94, 1.0, sv));
                        let edge_fade = edge_x * edge_y;
                        if edge_fade > 0.002 && (0.0..=1.0).contains(&su) && (0.0..=1.0).contains(&sv) {
                            let raw = master.sample_bilinear_srgb(su, sv);
                            let mx = raw[0].max(raw[1]).max(raw[2]);
                            if mx > 0.025 {
                                // Smooth volumetric cloud alpha from pure black background
                                let alpha = (sstep(0.025, 0.48, mx).powf(0.82) * edge_fade).clamp(0.0, 1.0);
                                // Un-premultiply black background so wispy edges stay bright & airy
                                let unpre = 1.0 / mx.max(0.22);
                                let mut rgb = [0.0f32; 3];
                                for c in 0..3 {
                                    let base_c = (raw[c] * unpre).clamp(0.0, 1.0);
                                    let tinted = base_c * (0.72 + 0.28 * ca[c]);
                                    rgb[c] = tinted.clamp(0.0, 1.0);
                                }
                                let r8 = (rgb[0] * 255.0 + 0.5) as u8;
                                let g8 = (rgb[1] * 255.0 + 0.5) as u8;
                                let b8 = (rgb[2] * 255.0 + 0.5) as u8;
                                let a8 = (alpha * 255.0 + 0.5) as u8;
                                *slot = pack_rgba8_f32(r8, g8, b8, a8);
                            }
                        }
                    }
                });
        }
        _ => {}
    }

    if blur > 0.5 {
        let radius = ((blur / 100.0) * (out_w as f32 * 0.008)).round() as usize;
        if radius > 0 {
            rgba_words = box_blur_packed_rgba8(&rgba_words, out_w, out_h, radius);
        }
    }

    rgba_words
}

/// Extracts clean, halo-free RGBA `[r, g, b, a]` in `0..1` for a bird pixel from a 4K Nano Banana
/// bird master plate (either dark/feathered birds on a pure white `#FFFFFF` background, or white
/// wedding doves on a pure black `#000000` background).
#[inline]
fn extract_bird_rgba(
    raw: [f32; 3],
    on_white_bg: bool,
    ca: [f32; 3],
    cb: [f32; 3],
    tint_strength: f32,
) -> [f32; 4] {
    if on_white_bg {
        let min_c = raw[0].min(raw[1]).min(raw[2]);
        let lum = 0.2126 * raw[0] + 0.7152 * raw[1] + 0.0722 * raw[2];
        let bg_metric = 0.65 * min_c + 0.35 * lum;
        if bg_metric >= 0.942 {
            return [0.0; 4];
        }
        // Any bird interior pixel (including light-grey seagull bellies and eagle feather highlights)
        // with bg_metric <= 0.855 is 100% opaque; 0.855..0.942 is the anti-aliased feather edge.
        let alpha = (1.0 - sstep(0.855, 0.942, bg_metric)).clamp(0.0, 1.0);
        // Un-premultiply the white background (`bg = 1.0`) along semi-transparent feather tips
        let inv_a = 1.0 / alpha.max(0.08);
        let mut rgb = [
            ((raw[0] - (1.0 - alpha)) * inv_a).clamp(0.0, 1.0),
            ((raw[1] - (1.0 - alpha)) * inv_a).clamp(0.0, 1.0),
            ((raw[2] - (1.0 - alpha)) * inv_a).clamp(0.0, 1.0),
        ];
        if tint_strength > 0.01 {
            for c in 0..3 {
                let warm = rgb[c] * (0.65 + 0.55 * cb[c]) + ca[c] * 0.14;
                rgb[c] = (rgb[c] * (1.0 - tint_strength) + warm * tint_strength).clamp(0.0, 1.0);
            }
        }
        [rgb[0], rgb[1], rgb[2], alpha]
    } else {
        // White wedding doves on pure black (`#000000`) background
        let max_c = raw[0].max(raw[1]).max(raw[2]);
        if max_c <= 0.045 {
            return [0.0; 4];
        }
        let alpha = sstep(0.045, 0.20, max_c).clamp(0.0, 1.0);
        let inv_a = 1.0 / alpha.max(0.10);
        let rgb = [
            (raw[0] * inv_a).clamp(0.0, 1.0),
            (raw[1] * inv_a).clamp(0.0, 1.0),
            (raw[2] * inv_a).clamp(0.0, 1.0),
        ];
        [rgb[0], rgb[1], rgb[2], alpha]
    }
}

/// Fast parallel separable box blur on packed RGBA8 `f32` words.
pub fn box_blur_packed_rgba8(src: &[f32], w: usize, h: usize, radius: usize) -> Vec<f32> {
    let r = radius.clamp(1, 32);
    let mut tmp = vec![0.0f32; w * h];
    tmp.par_chunks_mut(w).enumerate().for_each(|(y, row)| {
        let row_src = &src[y * w..(y + 1) * w];
        for (x, slot) in row.iter_mut().enumerate() {
            let x0 = x.saturating_sub(r);
            let x1 = (x + r).min(w - 1);
            let inv = 1.0 / ((x1 - x0 + 1) as f32);
            let mut sum = [0.0f32; 4];
            for &word in &row_src[x0..=x1] {
                let rgba = unpack_rgba8_f32(word);
                sum[0] += rgba[0];
                sum[1] += rgba[1];
                sum[2] += rgba[2];
                sum[3] += rgba[3];
            }
            *slot = pack_rgba8_f32(
                (sum[0] * inv * 255.0 + 0.5) as u8,
                (sum[1] * inv * 255.0 + 0.5) as u8,
                (sum[2] * inv * 255.0 + 0.5) as u8,
                (sum[3] * inv * 255.0 + 0.5) as u8,
            );
        }
    });

    let mut out = vec![0.0f32; w * h];
    out.par_chunks_mut(w).enumerate().for_each(|(y, row)| {
        let y0 = y.saturating_sub(r);
        let y1 = (y + r).min(h - 1);
        let inv = 1.0 / ((y1 - y0 + 1) as f32);
        for (x, slot) in row.iter_mut().enumerate() {
            let mut sum = [0.0f32; 4];
            for yy in y0..=y1 {
                let rgba = unpack_rgba8_f32(tmp[yy * w + x]);
                sum[0] += rgba[0];
                sum[1] += rgba[1];
                sum[2] += rgba[2];
                sum[3] += rgba[3];
            }
            *slot = pack_rgba8_f32(
                (sum[0] * inv * 255.0 + 0.5) as u8,
                (sum[1] * inv * 255.0 + 0.5) as u8,
                (sum[2] * inv * 255.0 + 0.5) as u8,
                (sum[3] * inv * 255.0 + 0.5) as u8,
            );
        }
    });
    out
}

/// Renders an RGBA8 thumbnail (`tw × th × 4` bytes) for SmartSky card `preset` (`1..=100`).
pub fn sky_thumb_rgba8(preset: u16, tw: usize, th: usize) -> Vec<u8> {
    let cat = crate::smart_sky::catalog();
    let idx = (preset.saturating_sub(1) as usize).min(cat.len().saturating_sub(1));
    let packed = build_sky_packed_map(&cat[idx], tw, th, 0.0);
    let mut out = vec![0u8; tw * th * 4];
    for (i, &w) in packed.iter().enumerate() {
        let [r, g, b, _] = unpack_rgba8_f32(w);
        let o = i * 4;
        out[o] = (r * 255.0 + 0.5) as u8;
        out[o + 1] = (g * 255.0 + 0.5) as u8;
        out[o + 2] = (b * 255.0 + 0.5) as u8;
        out[o + 3] = 255;
    }
    out
}

/// Renders an RGBA8 thumbnail (`tw × th × 4` bytes) for Nature Overlay card `preset` (`151..=200`).
pub fn nature_overlay_thumb_rgba8(preset: u16, tw: usize, th: usize) -> Vec<u8> {
    let cat = crate::overlays::catalog();
    let idx = (preset.saturating_sub(1) as usize).min(cat.len().saturating_sub(1));
    let spec = &cat[idx];
    let packed = build_nature_overlay_packed_map(spec, tw, th, 0.0);
    let is_birds = spec.category == OverlayCategory::Birds;
    let mut out = vec![0u8; tw * th * 4];
    for y in 0..th {
        let ty = y as f32 / th.max(1) as f32;
        let bg = if is_birds {
            [
                0.28 + 0.38 * ty,
                0.38 + 0.36 * ty,
                0.56 + 0.28 * ty,
            ]
        } else {
            [
                0.09 + 0.12 * ty,
                0.13 + 0.15 * ty,
                0.22 + 0.18 * ty,
            ]
        };
        for x in 0..tw {
            let i = y * tw + x;
            let [r, g, b, a] = unpack_rgba8_f32(packed[i]);
            let o = i * 4;
            let (cr, cg, cb) = if matches!(spec.category, OverlayCategory::Birds | OverlayCategory::Clouds) {
                (
                    bg[0] * (1.0 - a) + r * a,
                    bg[1] * (1.0 - a) + g * a,
                    bg[2] * (1.0 - a) + b * a,
                )
            } else {
                (
                    1.0 - (1.0 - bg[0]) * (1.0 - (r * a).min(1.0)),
                    1.0 - (1.0 - bg[1]) * (1.0 - (g * a).min(1.0)),
                    1.0 - (1.0 - bg[2]) * (1.0 - (b * a).min(1.0)),
                )
            };
            out[o] = (cr.clamp(0.0, 1.0) * 255.0 + 0.5) as u8;
            out[o + 1] = (cg.clamp(0.0, 1.0) * 255.0 + 0.5) as u8;
            out[o + 2] = (cb.clamp(0.0, 1.0) * 255.0 + 0.5) as u8;
            out[o + 3] = 255;
        }
    }
    out
}
